// GENERATED by scripts/vendor-engine.mjs — do not edit.
// Source: src/lib/data/types.ts. Run `npm run vendor` after changing the engine or pools.

/** Content types. Tiers are hidden from players — they only curate the deck curve. */
import type { IconName } from '../icons.ts';

export type Tier = 'bad' | 'mid' | 'good' | 'great';

/** Maps to `--<accent>` in `app.css`; every one carries black text at over 4.5:1. */
export type Accent = 'red' | 'yellow' | 'violet' | 'green' | 'blue';

/** Positions used by categories with a positional roster (NBA, NFL). */
export type Position = 'PG' | 'SG' | 'SF' | 'PF' | 'C' | 'QB' | 'RB' | 'WR' | 'TE';

/** What the per-category data files export. Hand-editable. */
export interface ItemSeed {
	name: string;
	tier: Tier;
	/** Optional flavour line under the name on the card. */
	note?: string;
	/** Required only for categories that define a `roster` template. */
	position?: Position;
}

/**
 * One roster slot. `drafts` shapes the deck and picks a default landing spot; it
 * deliberately does NOT restrict what can fill the slot. `null` means no positions.
 */
export interface SlotSpec {
	id: string;
	label: string;
	drafts: Position[] | null;
}

/** A seed with a stable id attached, built at import time by `variant()`. */
export interface Item extends ItemSeed {
	id: string;
}

/** A sub-pool. Sports have two ("Current", "All-Time"); everything else one. */
export interface Variant {
	id: string;
	label: string;
	items: Item[];
}

export interface Category {
	id: string;
	label: string;
	/** Font Awesome Free glyph, inlined from `$lib/icons`. */
	icon: IconName;
	blurb: string;
	/** Required, so a new category can't slip in colourless. */
	accent: Accent;
	/** No bundled items — the pool lives in `GameConfig.customItems`. */
	custom?: true;
	/** Length > 1 renders a toggle on the setup screen. */
	variants: Variant[];
	/** When present, roster size is locked to this template. */
	roster?: SlotSpec[];
}

/** Free-form slots, for every category without a positional template. */
export function openRoster(count: number): SlotSpec[] {
	return Array.from({ length: count }, (_, i) => ({
		id: `slot-${i + 1}`,
		label: `${i + 1}`,
		drafts: null
	}));
}

/** A natural fit, used only to suggest a default. Any item fits any open slot. */
export function slotSuits(slot: SlotSpec, item: ItemSeed): boolean {
	if (slot.drafts === null) return true;
	return !!item.position && slot.drafts.includes(item.position);
}

function slug(name: string): string {
	return name
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '');
}

/** Attaches collision-proof ids so data files stay clean to edit by hand. */
export function variant(id: string, label: string, seeds: ItemSeed[]): Variant {
	const seen = new Map<string, number>();
	const items = seeds.map((seed) => {
		const base = `${id}-${slug(seed.name)}`;
		const n = (seen.get(base) ?? 0) + 1;
		seen.set(base, n);
		return { ...seed, id: n === 1 ? base : `${base}-${n}` };
	});
	return { id, label, items };
}
